(function () {
'use strict';
function bindAccordion(container, itemSel, btnSel, panelSel) {
if (!container) return;
container.querySelectorAll(btnSel).forEach(function (btn) {
btn.addEventListener('click', function () {
var item = btn.closest(itemSel);
var panel = item.querySelector(panelSel);
var isOpen = item.classList.contains('is-open');
container.querySelectorAll(itemSel + '.is-open').forEach(function (open) {
open.classList.remove('is-open');
open.querySelector(btnSel).setAttribute('aria-expanded', 'false');
open.querySelector(panelSel).style.maxHeight = '0';
});
if (!isOpen) {
item.classList.add('is-open');
btn.setAttribute('aria-expanded', 'true');
panel.style.maxHeight = panel.scrollHeight + 'px';
}
});
});
}
function initFaqsPage() {
var list = document.getElementById('faqList');
var tabs = document.getElementById('faqTabs');
var search = document.getElementById('faqSearch');
var countEl = document.getElementById('faqCount');
if (!list) return;
var items = Array.prototype.slice.call(list.querySelectorAll('.faq-item'));
var emptyState = document.getElementById('faqEmpty');
var activeCat = 'all';
var query = '';
function render() {
var q = query.trim().toLowerCase();
var visible = 0;
items.forEach(function (item) {
var catOk = activeCat === 'all' || item.dataset.category === activeCat;
var searchOk = !q || (item.dataset.search || '').indexOf(q) !== -1;
var show = catOk && searchOk;
item.hidden = !show;
if (show) visible++;
});
if (countEl) countEl.textContent = visible + ' question' + (visible === 1 ? '' : 's');
if (emptyState) emptyState.hidden = visible !== 0;
}
bindAccordion(list, '.faq-item', '.faq-q', '.faq-a');
if (tabs) {
tabs.querySelectorAll('.faq-tab').forEach(function (tab) {
tab.addEventListener('click', function () {
tabs.querySelectorAll('.faq-tab').forEach(function (t) {
t.classList.remove('is-active');
});
tab.classList.add('is-active');
activeCat = tab.dataset.cat;
render();
});
});
}
search?.addEventListener('input', function () {
query = search.value;
render();
});
}
function initHomeFaqs() {
var list = document.getElementById('homeFaqList');
if (!list) return;
bindAccordion(list, '.home-faq-item', '.home-faq-q', '.home-faq-a');
}
document.addEventListener('DOMContentLoaded', function () {
lucide?.createIcons();
initFaqsPage();
initHomeFaqs();
});
})();